CREATE TABLE IF NOT EXISTS vision13_ebook_productions(id TEXT PRIMARY KEY,queue_id INTEGER NOT NULL UNIQUE,mix_id TEXT NOT NULL,approval_snapshot_hash TEXT NOT NULL,artifact_hash TEXT NOT NULL,object_key TEXT NOT NULL UNIQUE,file_size INTEGER NOT NULL DEFAULT 0,item_count INTEGER NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'completed',produced_by INTEGER NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(queue_id) REFERENCES vision13_intake_queue(id),FOREIGN KEY(mix_id) REFERENCES vision14_mixes(id),FOREIGN KEY(produced_by) REFERENCES users(id));
CREATE INDEX IF NOT EXISTS idx_v13_productions_created ON vision13_ebook_productions(created_at DESC);
